uot;,&quot;Folder&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;&quot;,&quot;IsExpression&quot;:false},&quot;StoreRelativeURL&quot;:&quot;&quot;,&quot;StorePhysicalPath&quot;:&quot;&quot;,&quot;StoreLinkClick&quot;:&quot;&quot;,&quot;DisableForceDownload&quot;:&quot;&quot;},&quot;IsDeleted&quot;:false},&quot;EventName&quot;:&quot;BulkAction&quot;,&quot;IsDeleted&quot;:false},{&quot;Id&quot;:0,&quot;ButtonId&quot;:0,&quot;ActionInfo&quot;:{&quot;ActionErrorMessage&quot;:null,&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Export.RedirectUrl&quot;},&quot;Id&quot;:0,&quot;Description&quot;:null,&quot;ActionType&quot;:&quot;RedirectToUrl&quot;,&quot;OrderIndex&quot;:1,&quot;Condition&quot;:null,&quot;Parameters&quot;:{&quot;Url&quot;:&quot;[ExcelUrl]&quot;,&quot;ForceDownload&quot;:true,&quot;EscapeUrl&quot;:&quot;&quot;,&quot;OpenInPopup&quot;:&quot;&quot;,&quot;PopupTitle&quot;:&quot;&quot;,&quot;OpenInNewTab&quot;:&quot;&quot;},&quot;IsDeleted&quot;:false},&quot;EventName&quot;:&quot;BulkAction&quot;,&quot;IsDeleted&quot;:false}],&quot;BulkActionsAfter&quot;:[],&quot;ItemActions&quot;:[],&quot;Url&quot;:&quot;&amp;amp;buttonName=Export&quot;,&quot;ModuleId&quot;:906,&quot;AutoName&quot;:true,&quot;Name&quot;:&quot;Export&quot;,&quot;Title&quot;:&quot;Export&quot;,&quot;Help&quot;:&quot;Export&quot;,&quot;ShowCondition&quot;:null,&quot;IsEnabled&quot;:false,&quot;Metadata&quot;:{&quot;PAP_InternalIdentifier&quot;:&quot;Button.Export&quot;},&quot;Type&quot;:&quot;GridButton&quot;,&quot;OrderIndex&quot;:1,&quot;CssClass&quot;:&quot;link&quot;,&quot;CustomCssClass&quot;:null,&quot;IconClass&quot;:null,&quot;FaIconClass&quot;:null,&quot;PermissionAllUsers&quot;:false,&quot;PermissionsExportJson&quot;:&quot;[\&quot;Users\&quot;,\&quot;Admins\&quot;,\&quot;Citizen Developers\&quot;,\&quot;Low-Code Engineer\&quot;,\&quot;Managers\&quot;]&quot;,&quot;Permissions&quot;:[9,6,7,5,8],&quot;AskForConfirmation&quot;:false,&quot;ConfirmationMessage&quot;:null,&quot;ConfirmationOk&quot;:null,&quot;ConfirmationCancel&quot;:null,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:null,&quot;IsDeleted&quot;:false},{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Top&quot;,&quot;HorizontalPosition&quot;:&quot;Right&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:0,&quot;ButtonId&quot;:0,&quot;ActionInfo&quot;:{&quot;ActionErrorMessage&quot;:null,&quot;Metadata&quot;:{},&quot;Id&quot;:0,&quot;Description&quot;:null,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;OrderIndex&quot;:0,&quot;Condition&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;;WITH NrMandate AS\n(\n    SELECT COUNT(*) AS Nr\n    FROM app.PensieAlimentara\n    WHERE Anul = @Anul\n      AND Luna = @Luna\n      AND CodSucursala = @CodSucursala\n)\n\nUPDATE p\nSET \n    Taxa =\n        CASE \n            WHEN LEFT(p.CodSucursala,1) IN (&#39;A&#39;,&#39;G&#39;) THEN 0\n\n            WHEN LEFT(p.CodSucursala,1) = &#39;W&#39;\n                 OR nm.Nr &amp;gt; 10 THEN\n                ROUND((p.Rata + ISNULL(p.Rest,0)) * 0.011,0)\n                + ISNULL(t.TaxaInregistrare,0)\n                + CASE WHEN p.PostRestant = 1 \n                       THEN ISNULL(t.TaxaPOSTRESTANT,0)\n                       ELSE 0 END\n\n            ELSE\n                CASE \n                    WHEN (p.Rata + ISNULL(p.Rest,0)) &amp;lt;= 200  THEN 5\n                    WHEN (p.Rata + ISNULL(p.Rest,0)) &amp;lt;= 500  THEN 10\n                    WHEN (p.Rata + ISNULL(p.Rest,0)) &amp;lt;= 1000 THEN 15\n                    ELSE ROUND((p.Rata + ISNULL(p.Rest,0)) * 0.01,0) + 15\n                END\n                + CASE WHEN p.PostRestant = 1 \n                       THEN ISNULL(t.TaxaPOSTRESTANT,0)\n                       ELSE 0 END\n        END,\n\n    Taxam = ISNULL(t.ValoareFormularMandat,0),\n\n    StatusCalculTaxe = 1\n\nFROM app.PensieAlimentara p\nCROSS JOIN NrMandate nm\nCROSS JOIN (SELECT TOP 1 * FROM app.TSTaxaMandatPostal) t\nWHERE p.Anul = @Anul\n  AND p.Luna = @Luna\n  AND p.CodSucursala = @CodSucursala;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:&quot;taxe&quot;,&quot;ExtractColumns&quot;:&quot;&quot;,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false},&quot;IsDeleted&quot;:false},&quot;EventName&quot;:&quot;BulkAction&quot;,&quot;IsDeleted&quot;:false},{&quot;Id&quot;:0,&quot;ButtonId&quot;:0,&quot;ActionInfo&quot;:{&quot;ActionErrorMessage&quot;:null,&quot;Metadata&quot;:{},&quot;Id&quot;:0,&quot;Description&quot;:null,&quot;ActionType&quot;:&quot;RefreshGrid&quot;,&quot;OrderIndex&quot;:1,&quot;Condition&quot;:null,&quot;Parameters&quot;:{&quot;ModuleId&quot;:{&quot;Expression&quot;:&quot;&quot;,&quot;Value&quot;:&quot;f897370f-a50b-4680-bb56-33079695e9f6&quot;,&quot;IsExpression&quot;:false,&quot;Parameters&quot;:{}}},&quot;IsDeleted&quot;:false},&quot;EventName&quot;:&quot;BulkAction&quot;,&quot;IsDeleted&quot;:false}],&quot;BulkActionsAfter&quot;:[],&quot;ItemActions&quot;:[],&quot;Url&quot;:&quot;&amp;amp;buttonName=CalculTaxeMandate&quot;,&quot;ModuleId&quot;:906,&quot;AutoName&quot;:false,&quot;Name&quot;:&quot;CalculTaxeMandate&quot;,&quot;Title&quot;:&quot;Calcul Taxe Mandate&quot;,&quot;Help&quot;:null,&quot;ShowCondition&quot;:null,&quot;IsEnabled&quot;:false,&quot;Metadata&quot;:{},&quot;Type&quot;:&quot;GridButton&quot;,&quot;OrderIndex&quot;:2,&quot;CssClass&quot;:&quot;warning&quot;,&quot;CustomCssClass&quot;:null,&quot;IconClass&quot;:null,&quot;FaIconClass&quot;:null,&quot;PermissionAllUsers&quot;:true,&quot;PermissionsExportJson&quot;:&quot;[]&quot;,&quot;Permissions&quot;:[],&quot;AskForConfirmation&quot;:false,&quot;ConfirmationMessage&quot;:&quot;Are you sure you want to do this?&quot;,&quot;ConfirmationOk&quot;:&quot;Yes, pretty sure&quot;,&quot;ConfirmationCancel&quot;:&quot;No, I&#39;m having second thoughts&quot;,&quot;JsCode&quot;:null,&quot;IsClientButton&quot;:false,&quot;ButtonGroupId&quot;:null,&quot;ButtonGroupName&quot;:null,&quot;Id&quot;:0,&quot;EnableCondition&quot;:&quot;[Helper:TokenStatusCalculTaxePostale] == 1 &amp;amp;&amp;amp; [Helper:TokenStatusCalculLichidare] == 1&quot;,&quot;IsDeleted&quot;:false},{&quot;EnableSelection&quot;:false,&quot;RequiresSelection&quot;:false,&quot;RequiresData&quot;:false,&quot;ShowCount&quot;:false,&quot;SumColumn&quot;:null,&quot;SumMode&quot;:&quot;Default&quot;,&quot;SumCoefficient&quot;:null,&quot;TextBeforeSum&quot;:null,&quot;TextAfterSum&quot;:null,&quot;ConfirmationPosition&quot;:&quot;centered&quot;,&quot;VerticalPosition&quot;:&quot;Top&quot;,&quot;HorizontalPosition&quot;:&quot;Right&quot;,&quot;BulkActions&quot;:[{&quot;Id&quot;:0,&quot;ButtonId&quot;:0,&quot;ActionInfo&quot;:{&quot;ActionErrorMessage&quot;:null,&quot;Metadata&quot;:{},&quot;Id&quot;:0,&quot;Description&quot;:&quot;Verificare taxe postale Pensii Alimentare necalculate&quot;,&quot;ActionType&quot;:&quot;ExecuteActions&quot;,&quot;OrderIndex&quot;:0,&quot;Condition&quot;:null,&quot;Parameters&quot;:{&quot;ActionList&quot;:[{&quot;Title&quot;:&quot;Run SQL Query&quot;,&quot;ActionType&quot;:&quot;RunSql&quot;,&quot;Description&quot;:&quot;Verificare taxe postale necalculate&quot;,&quot;Condition&quot;:null,&quot;Parameters&quot;:{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:&quot;&quot;,&quot;QueryTimeout&quot;:&quot;&quot;,&quot;SqlQuery&quot;:&quot;SELECT COUNT(*) AS NrNecalculate\nFROM app.PensieAlimentara\nWHERE Anul = @Anul\n  AND Luna = @Luna\n  AND CodSucursala = @CodSucursala\n  AND (StatusCalculTaxe = 1 or StatusCalcultaxe is NULL)\n  AND (Taxa IS NULL or Taxam is NULL);&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:BranchV]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[GetOrSession:MonthV]&quot;,&quot;name&quot;:&quot;Luna&quot;}],&quot;OutputTokenName&quot;:&quot;NrNecalculate&quot;,&quot;ExtractColumns&quot;:&quot;&quot;,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false},&quot;$_uid&quot;:&quot;action17731386542397458&quot;,&quot;$_isOpen&quot;:false,&quot;$_isLoaded&quot;:true,&quot;$_isFocus&quot;:true,&quot;EventName&quot;:&quot;click&quot;,&quot;Definition&quot;:{&quot;Id&quot;:&quot;RunSql&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Run SQL Query&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Executes the specified SQL query, optionally storing the output for use in other actions.&quot;},&quot;TypeStr&quot;:&quot;DnnSharp.Common.Actions.Data.ExecuteSql, DnnSharp.Common.Actions&quot;,&quot;Final&quot;:false,&quot;IsClientAction&quot;:false,&quot;Groups&quot;:[],&quot;Parameters&quot;:[{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;DbConnector&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Database&quot;},&quot;HelpText&quot;:{},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;ActionCredentials&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;Selection&quot;:&quot;Single&quot;,&quot;Type&quot;:&quot;Database&quot;},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[{&quot;TypeStr&quot;:&quot;DnnSharp.Common2.Services.PlantAnApp.ConfigConditions.IsPlantAnApp,DnnSharp.Common2&quot;,&quot;Settings&quot;:{}}],&quot;$_cleanHashKey&quot;:&quot;17726282701957462&quot;},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;ConnectionString&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Override Connection String&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;By default, the SQL will run against the built-in database or the selected Connection. Use this field to override the connection string. Also supports the name of a connection string from the web.config. It will respect the Provider (ODBC, SqlClient, etc.). Can contain Tokens. Read more about &amp;lt;a href=\&quot;http://www.connectionstrings.com/\&quot; target=\&quot;_blank\&quot;&amp;gt;supported formats&amp;lt;/a&amp;gt;.&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;QueryTimeout&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Query Timeout&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Set a time in seconds after which a query will time out. The default is set 10 minutes or 600 seconds also this parameter can&#39;t be negative or under 10 seconds. Can contain Tokens. &quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Text&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;SqlQuery&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;SQL Query&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;SQL to execute. Can contain Tokens. &amp;lt;br/&amp;gt; &amp;lt;div style=\&quot;color:red\&quot;&amp;gt;WARNING!&amp;lt;/div&amp;gt; We encourage using binding parameters instead of using the tokens directly on sql query. Just use @param instead of [token] and bind below values as shown: Parameter Name: param ; Parameter Value: [token]. This will keep your database safe.&amp;lt;br/&amp;gt;&quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;Code&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;CodeMirrorMode&quot;:&quot;sql&quot;,&quot;AiAssist&quot;:&quot;sql&quot;},&quot;Validation&quot;:[{&quot;Type&quot;:&quot;Required&quot;,&quot;From&quot;:null,&quot;For&quot;:null,&quot;Settings&quot;:{}}],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;BindTokens&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Bind Tokens&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Bind the parameters above with a value or token. e.g. P. Name:param, P. Value:[token] &quot;},&quot;Placeholder&quot;:{},&quot;DefaultValue&quot;:{},&quot;Default&quot;:null,&quot;Type&quot;:&quot;NameValueCollection&quot;,&quot;IsPublic&quot;:false,&quot;Settings&quot;:{&quot;NameColumn&quot;:&quot;Parameter Name&quot;,&quot;ValueColumn&quot;:&quot;Parameter Value&quot;,&quot;ButtonName&quot;:&quot;Bind more data&quot;},&quot;Validation&quot;:[],&quot;Groups&quot;:null,&quot;Parameters&quot;:[],&quot;Conditions&quot;:[]},{&quot;For&quot;:null,&quot;NotFor&quot;:null,&quot;Id&quot;:&quot;OutputTokenName&quot;,&quot;Title&quot;:{&quot;default&quot;:&quot;Store Result&quot;},&quot;HelpText&quot;:{&quot;default&quot;:&quot;Optionally, provid